<?php $rows=$pdo->query("SELECT c.*,v.name vendor_name FROM contracts c LEFT JOIN vendors v ON v.id=c.vendor_id ORDER BY c.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Contract Management</h2></div><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Contract</th><th>Vendor</th><th>Title</th><th>Value</th><th>Period</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['contract_no']?></td><td><?=$r['vendor_name']?></td><td><?=$r['title']?></td><td>Rp <?=number_format($r['contract_value'],0,',','.')?></td><td><?=$r['start_date']?> s/d <?=$r['end_date']?></td><td><?=$r['status']?></td></tr><?php endforeach;?></tbody></table></div></div>